/**
 * 日漫拟声字视觉插件 / Manga SFX Visualizer
 * v0.1.1 standalone
 * Target: Tavern Helper / JS-Slash-Runner
 */
(() => {
  'use strict';

  const VERSION = '0.1.1';
  const ROOT_ID = 'manga-sfx-visualizer-root';
  const STYLE_ID = 'manga-sfx-visualizer-style';
  const MAX_CUES = 4;
  const MAX_TEXT = 24;
  const SEEN = new Set();

  const TYPES = Object.freeze({
    impact: 'impact', warcry: 'impact', hit: 'impact',
    rumble: 'rumble', pressure: 'rumble', aura: 'rumble',
    shock: 'shock', surprise: 'shock', stun: 'shock',
  });

  const hostWindow = window.parent || window;
  const hostDocument = hostWindow.document || document;

  function typeOf(value) {
    return TYPES[String(value || 'impact').trim().toLowerCase()] || 'impact';
  }

  function cleanText(value) {
    return String(value ?? '')
      .replace(/<[^>]*>/g, '')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, MAX_TEXT);
  }

  function ensureStage() {
    if (!hostDocument?.body) return null;

    let style = hostDocument.getElementById(STYLE_ID);
    if (!style) {
      style = hostDocument.createElement('style');
      style.id = STYLE_ID;
      style.textContent = `
#${ROOT_ID}{
  position:fixed!important;
  left:0!important;top:0!important;
  width:100vw!important;height:100vh!important;
  z-index:2147483646!important;
  pointer-events:none!important;
  overflow:hidden!important;
}
#${ROOT_ID} .mfx-sfx{
  position:absolute!important;
  pointer-events:none!important;
  user-select:none!important;
  white-space:pre!important;
  line-height:.92!important;
  font-family:"Noto Sans JP","Yu Gothic","Hiragino Kaku Gothic ProN","Arial Black","Impact",system-ui,sans-serif!important;
  font-weight:900!important;
  color:#111!important;
  -webkit-text-stroke:2px rgba(255,255,255,.98)!important;
  paint-order:stroke fill!important;
  text-shadow:0 3px 0 rgba(255,255,255,.9),0 8px 24px rgba(0,0,0,.55)!important;
  will-change:transform,opacity!important;
}
#${ROOT_ID} .mfx-impact{
  left:50%!important;top:44%!important;
  font-size:clamp(58px,15vw,156px)!important;
  animation:mfxImpact 1200ms cubic-bezier(.12,.8,.24,1) both!important;
}
#${ROOT_ID} .mfx-rumble{
  right:4vw!important;top:14%!important;
  font-size:clamp(42px,10vw,100px)!important;
  writing-mode:vertical-rl!important;
  letter-spacing:.05em!important;
  animation:mfxRumble 1700ms ease-out both!important;
}
#${ROOT_ID} .mfx-shock{
  left:50%!important;top:10%!important;
  font-size:clamp(52px,12vw,120px)!important;
  animation:mfxShock 1350ms cubic-bezier(.16,.82,.24,1) both!important;
}
@keyframes mfxImpact{
  0%{opacity:0;transform:translate(-50%,-50%) rotate(-12deg) scale(.12)}
  18%{opacity:1;transform:translate(-50%,-50%) rotate(-4deg) scale(1.18)}
  34%{transform:translate(-50%,-50%) rotate(-8deg) scale(.94)}
  52%{transform:translate(-50%,-50%) rotate(-5deg) scale(1.02)}
  78%{opacity:1;transform:translate(-50%,-50%) rotate(-5deg) scale(1)}
  100%{opacity:0;transform:translate(-50%,-50%) rotate(-3deg) scale(1.08)}
}
@keyframes mfxRumble{
  0%{opacity:0;transform:rotate(7deg) translateX(42px)}
  20%{opacity:.95;transform:rotate(4deg) translateX(0)}
  42%{transform:rotate(6deg) translateX(4px)}
  58%{transform:rotate(4deg) translateX(-3px)}
  78%{opacity:.95}
  100%{opacity:0;transform:rotate(5deg) translateX(-18px)}
}
@keyframes mfxShock{
  0%{opacity:0;transform:translate(-50%,-150%) rotate(3deg) scale(.88)}
  24%{opacity:1;transform:translate(-50%,18%) rotate(-2deg) scale(1.1)}
  40%{transform:translate(-50%,-3%) rotate(1deg) scale(.98)}
  56%{transform:translate(-50%,5%) rotate(-1deg) scale(1.01)}
  80%{opacity:1}
  100%{opacity:0;transform:translate(-50%,2%) rotate(0) scale(1.04)}
}
@media(prefers-reduced-motion:reduce){
  #${ROOT_ID} .mfx-sfx{animation-duration:650ms!important}
}`;
      (hostDocument.head || hostDocument.documentElement).appendChild(style);
    }

    let root = hostDocument.getElementById(ROOT_ID);
    if (!root) {
      root = hostDocument.createElement('div');
      root.id = ROOT_ID;
      root.setAttribute('aria-hidden', 'true');
      hostDocument.body.appendChild(root);
    }
    return root;
  }

  function showCue(cue, delay = 0) {
    hostWindow.setTimeout(() => {
      const root = ensureStage();
      if (!root) return;

      const node = hostDocument.createElement('div');
      node.className = `mfx-sfx mfx-${typeOf(cue.type)}`;
      node.textContent = cleanText(cue.text);
      if (!node.textContent) return;

      root.appendChild(node);
      const remove = () => node.remove();
      node.addEventListener('animationend', remove, { once: true });
      hostWindow.setTimeout(remove, 2400);
    }, Math.max(0, delay));
  }

  function play(cues) {
    cues.slice(0, MAX_CUES).forEach((cue, i) => showCue(cue, i * 300));
  }

  function parseCues(source) {
    const input = String(source ?? '');
    const cues = [];
    let m;

    const commentRe = /<!--\s*SFX(?:\s*:\s*([a-zA-Z_-]+))?\s*\|\s*([\s\S]*?)\s*-->/gi;
    while ((m = commentRe.exec(input)) && cues.length < MAX_CUES) {
      const text = cleanText(m[2]);
      if (text) cues.push({ type: typeOf(m[1]), text });
    }

    const tagRe = /<sfx(?:\s+type\s*=\s*["']?([a-zA-Z_-]+)["']?)?\s*>([\s\S]*?)<\/sfx>/gi;
    while ((m = tagRe.exec(input)) && cues.length < MAX_CUES) {
      const text = cleanText(m[2]);
      if (text) cues.push({ type: typeOf(m[1]), text });
    }
    return cues;
  }

  function hash(text) {
    const s = String(text ?? '');
    let h = 2166136261;
    for (let i = 0; i < s.length; i += 1) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0).toString(36);
  }

  function processMessage(messageId) {
    if (typeof getChatMessages !== 'function') return;
    try {
      const list = getChatMessages(Number(messageId), { role: 'assistant', include_swipes: false });
      const msg = list?.[0];
      const text = msg?.message ?? msg?.mes ?? '';
      if (!text) return;

      const fp = `${messageId}:${hash(text)}`;
      if (SEEN.has(fp)) return;
      SEEN.add(fp);
      if (SEEN.size > 160) SEEN.delete(SEEN.values().next().value);

      const cues = parseCues(text);
      if (cues.length) play(cues);
    } catch (err) {
      console.warn(`[MangaSFX v${VERSION}] message parse failed`, err);
    }
  }

  function preview() {
    showCue({ type: 'impact', text: 'ドン！！' }, 0);
    showCue({ type: 'rumble', text: 'ゴゴゴゴゴ……' }, 700);
    showCue({ type: 'shock', text: 'ガーン！' }, 1450);
  }

  function safeWrap(fn) {
    return typeof errorCatched === 'function' ? errorCatched(fn) : fn;
  }

  function boot() {
    if (!ensureStage()) {
      hostWindow.setTimeout(boot, 250);
      return;
    }

    window.MangaSFXPreview = preview;

    if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
      try {
        eventOn(getButtonEvent('拟声字预览'), safeWrap(preview));
      } catch (err) {
        console.warn(`[MangaSFX v${VERSION}] preview button bind failed`, err);
      }
    } else {
      console.warn(`[MangaSFX v${VERSION}] Tavern Helper event API unavailable`);
    }

    if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined' && tavern_events?.MESSAGE_RECEIVED) {
      try {
        eventOn(tavern_events.MESSAGE_RECEIVED, safeWrap((messageId) => processMessage(messageId)));
      } catch (err) {
        console.warn(`[MangaSFX v${VERSION}] MESSAGE_RECEIVED bind failed`, err);
      }
    }

    window.addEventListener('pagehide', () => {
      hostDocument.getElementById(ROOT_ID)?.remove();
      hostDocument.getElementById(STYLE_ID)?.remove();
    }, { once: true });

    console.info(`[MangaSFX v${VERSION}] standalone ready`);
  }

  boot();
})();
